#include <iostream>
#include <string>
#include <algorithm>
std::string addStrings(std::string a, std::string b){
  std::string r; int i=(int)a.size()-1, j=(int)b.size()-1, c=0;
  while(i>=0||j>=0||c){int x=i>=0?a[i--]-'0':0;int y=j>=0?b[j--]-'0':0;int s=x+y+c;r+=char(s%10+'0');c=s/10;}
  std::reverse(r.begin(),r.end());return r;
}
int main(){std::cout<<addStrings("11","123");}
